parameters.jsCode:
const response = $input.first().json;
let parsed = {};

try {
  const rawText = response.candidates[0].content.parts[0].text;
  const jsonStart = rawText.indexOf('{');
  const jsonEnd = rawText.lastIndexOf('}');
  if (jsonStart !== -1 && jsonEnd !== -1) {
    parsed = JSON.parse(rawText.substring(jsonStart, jsonEnd + 1));
  } else {
    parsed = JSON.parse(rawText);
  }
} catch (e) {
  parsed = {
    topic: "4K Commercial Reels vs Physical Shoots",
    title: "Sutra Studio • 4K Commercial Video & 3D CGI Engine",
    hook: "Stop spending ₹5 Lakhs on camera crews for your product videos.",
    caption: "🚀 Transform your brand presence with 4K Commercial Reels & 3D CGI from SUTRA STUDIO.\n\nTraditional physical shoots take weeks and cost a fortune. Sutra Studio crafts photorealistic 4K reels and spatial 3D renders with a 48-72h turnaround:\n\n✨ 30 Commercial Reels / Month\n✨ 4K Architectural & Spatial Visualization\n✨ Transparent Indian Pricing: ₹9,999 / ₹19,999 per month\n\nWhatsApp Concierge: +91 82001 92781\nExplore: sutrastudios.in",
    hashtags: ["#SutraStudio", "#CommercialReels", "#3DVisualization", "#CreativeTechnology", "#MetaAds"],
    reelScript: {
      openingHook: "Stop spending ₹5 Lakhs on camera crews for your product videos.",
      scenes: [
        { timestamp: "0:00 - 0:03", visualCue: "Dynamic 3D product render sweep", voiceoverOrText: "Stop spending fortunes on physical studio shoots." },
        { timestamp: "0:03 - 0:07", visualCue: "Instant 4K CGI rendering comparison", voiceoverOrText: "Sutra Studio engineers 4K commercial reels in 48 hours." },
        { timestamp: "0:07 - 0:11", visualCue: "Pricing card showing ₹9,999 / ₹19,999", voiceoverOrText: "30 commercial reels per month. Zero friction." },
        { timestamp: "0:11 - 0:15", visualCue: "WhatsApp CTA screen", voiceoverOrText: "WhatsApp +91 82001 92781 to start." }
      ],
      audioRecommendation: "120 BPM Deep Luxury Ambient Beat with Subtle Indian Percussion",
      callToAction: "WhatsApp +91 82001 92781 to claim your 48h Studio Reel"
    },
    imagePrompt: "luxury modern Indian architectural villa with warm ambient lighting, teakwood jali screen, reflecting pool golden hour 8k commercial photography",
    metaAdCopy: {
      primaryText: "4K Commercial Reels & 3D CGI engineered for high-growth brands. 48h delivery from ₹9,999/mo.",
      headline: "Sutra Studio • 4K Commercial Reels & 3D",
      description: "48h Delivery • WhatsApp Concierge",
      targetAudienceInterests: ["Luxury Goods", "Architecture", "Digital Marketing"]
    }
  };
}

// Generate Dynamic AI Image URL (Pollinations Gen API / Proxy with random seed)
const randomSeed = Math.floor(Math.random() * 900000) + 100000;
const promptParam = encodeURIComponent(parsed.imagePrompt || 'luxury commercial advertising 8k warm ivory and brass');
const sutraBaseUrl = $env.SUTRA_STUDIO_URL || 'https://sutrastudios.in';
const dynamicImageUrl = `${sutraBaseUrl}/api/media/image?prompt=${promptParam}&width=1200&height=800&seed=${randomSeed}&fallback=images/projects/proj-villa.webp`;

// Verified high-resolution commercial reel
const dynamicVideoUrl = `${sutraBaseUrl}/videos/services/ai-video-mobile.mp4`;

const now = new Date().toISOString();
const runId = `sutra_n8n_promo_${Date.now()}`;

return [{
  json: {
    runId: runId,
    topic: parsed.topic,
    title: parsed.title,
    hook: parsed.hook,
    caption: parsed.caption,
    hashtags: parsed.hashtags,
    reelScript: parsed.reelScript,
    metaAdCopy: parsed.metaAdCopy,
    imagePrompt: parsed.imagePrompt,
    imageUrl: dynamicImageUrl,
    videoUrl: dynamicVideoUrl,
    mediaUrl: dynamicVideoUrl,
    mediaType: 'video',
    sutraBaseUrl: sutraBaseUrl,
    sutraSecret: $env.N8N_WEBHOOK_SECRET || '',
    whatsappUrl: 'https://wa.me/918200192781?text=' + encodeURIComponent(`Hello Sutra Studio! I am reviewing the 4K Drop: "${parsed.title}". Hook: "${parsed.hook}". I would like to inquire about this for my business.`),
    createdAt: now,
    fbPageId: $env.FACEBOOK_PAGE_ID || '61594200943169',
    igUserId: $env.INSTAGRAM_ACCOUNT_ID || '',
    metaToken: $env.META_GRAPH_ACCESS_TOKEN || ''
  }
}];
